import csv, re
path='/root/data/stock-descriptions.csv'
cols=['ticker','sector','full name','marketCap']
non_ascii=set()
with open(path,'r',encoding='utf-8') as f:
    reader=csv.DictReader(f)
    for r in reader:
        for c in cols:
            val=r[c]
            for ch in val:
                if ord(ch) > 127:
                    non_ascii.add(ch)
if non_ascii:
    print('non-ascii found:', ''.join(sorted(non_ascii)))
else:
    print('no non-ascii in selected cols')
