(() => {
  const stockData = window.STOCK_DATA || [];
  const priceSeries = window.PRICE_SERIES || {};

  const svg = d3.select('#bubble-chart');
  const chartPanel = document.getElementById('chart-panel');
  const tooltip = d3.select('#tooltip');

  if (!stockData.length) {
    svg.append('text')
      .attr('x', 20)
      .attr('y', 40)
      .text('No stock data loaded.');
    return;
  }

  const nodes = stockData.map((d) => ({
    ticker: d.ticker,
    sector: d.sector,
    fullName: d.fullName,
    marketCap: d.marketCap !== null && d.marketCap !== undefined ? +d.marketCap : null,
  }));

  nodes.forEach((d) => {
    d.isEtf = d.marketCap === null || d.sector === 'ETF';
  });

  const marketCaps = nodes
    .filter((d) => !d.isEtf && d.marketCap)
    .map((d) => d.marketCap);

  const rScale = d3.scaleSqrt()
    .domain(d3.extent(marketCaps))
    .range([12, 48]);

  const etfRadius = 16;
  nodes.forEach((d) => {
    d.r = d.isEtf ? etfRadius : rScale(d.marketCap);
  });

  const sectors = Array.from(new Set(nodes.map((d) => d.sector)));
  const color = d3.scaleOrdinal()
    .domain(sectors)
    .range(d3.schemeTableau10.slice(0, sectors.length));

  const bubbles = svg.append('g').attr('class', 'bubbles');
  const node = bubbles.selectAll('g.node')
    .data(nodes)
    .enter()
    .append('g')
    .attr('class', 'node');

  node.append('circle')
    .attr('r', (d) => d.r)
    .attr('fill', (d) => color(d.sector));

  node.append('text')
    .text((d) => d.ticker)
    .style('font-size', (d) => `${Math.max(9, Math.min(14, d.r * 0.6))}px`);

  let selectedTicker = null;

  function setSelected(ticker) {
    selectedTicker = ticker;
    node.classed('selected', (d) => d.ticker === selectedTicker);
    tableRows.classed('selected', (d) => d.ticker === selectedTicker);
  }

  function formatMarketCap(value) {
    if (value === null || Number.isNaN(value)) return 'N/A';
    const abs = Math.abs(value);
    const format = (num) => {
      const str = num.toFixed(2);
      return str.replace(/\.00$/, '').replace(/(\.[0-9])0$/, '$1');
    };
    if (abs >= 1e12) return `${format(value / 1e12)}T`;
    if (abs >= 1e9) return `${format(value / 1e9)}B`;
    if (abs >= 1e6) return `${format(value / 1e6)}M`;
    if (abs >= 1e3) return `${format(value / 1e3)}K`;
    return format(value);
  }

  const tableBody = d3.select('#stock-table tbody');
  const tableRows = tableBody.selectAll('tr')
    .data(nodes)
    .enter()
    .append('tr')
    .on('click', (event, d) => {
      event.stopPropagation();
      setSelected(d.ticker);
    });

  tableRows.append('td').text((d) => d.ticker);
  tableRows.append('td').text((d) => d.fullName);
  tableRows.append('td').text((d) => d.sector);
  tableRows.append('td')
    .attr('class', 'market-cap')
    .text((d) => formatMarketCap(d.marketCap));

  function renderLegend() {
    const legend = d3.select('#legend')
      .selectAll('div.legend-item')
      .data(sectors)
      .enter()
      .append('div')
      .attr('class', 'legend-item');

    legend.append('span')
      .attr('class', 'legend-swatch')
      .style('background-color', (d) => color(d));

    legend.append('span')
      .attr('class', 'legend-label')
      .text((d) => d);
  }

  renderLegend();

  function renderSparkline(container, series) {
    if (!series || !series.length) return;
    const width = 120;
    const height = 40;
    const padding = 3;

    const x = d3.scaleLinear()
      .domain([0, series.length - 1])
      .range([padding, width - padding]);

    const y = d3.scaleLinear()
      .domain(d3.extent(series))
      .range([height - padding, padding]);

    const line = d3.line()
      .x((_, i) => x(i))
      .y((d) => y(d));

    const svg = d3.select(container)
      .append('svg')
      .attr('class', 'sparkline')
      .attr('width', width)
      .attr('height', height);

    svg.append('path')
      .datum(series)
      .attr('d', line)
      .attr('fill', 'none')
      .attr('stroke', '#1b1b1b')
      .attr('stroke-width', 1.2);
  }

  function showTooltip(event, d) {
    if (d.isEtf) return;
    tooltip
      .style('opacity', 1)
      .html('');

    tooltip.append('div')
      .attr('class', 'tt-title')
      .text(d.ticker);

    tooltip.append('div')
      .attr('class', 'tt-sub')
      .text(d.fullName);

    tooltip.append('div')
      .attr('class', 'tt-sub')
      .text(d.sector);

    const series = priceSeries[d.ticker];
    renderSparkline(tooltip.node(), series);

    moveTooltip(event);
  }

  function moveTooltip(event) {
    const offset = 14;
    const { clientX, clientY } = event;
    const tooltipNode = tooltip.node();
    const { offsetWidth, offsetHeight } = tooltipNode;
    const left = clientX + offset + offsetWidth > window.innerWidth
      ? clientX - offsetWidth - offset
      : clientX + offset;
    const top = clientY + offset + offsetHeight > window.innerHeight
      ? clientY - offsetHeight - offset
      : clientY + offset;

    tooltip
      .style('left', `${left}px`)
      .style('top', `${top}px`);
  }

  function hideTooltip() {
    tooltip.style('opacity', 0);
  }

  node
    .on('mouseover', (event, d) => showTooltip(event, d))
    .on('mousemove', (event) => moveTooltip(event))
    .on('mouseout', () => hideTooltip())
    .on('click', (event, d) => {
      event.stopPropagation();
      setSelected(d.ticker);
    });

  svg.on('click', () => setSelected(null));

  let width = 0;
  let height = 0;
  let centers = {};

  function computeCenters() {
    const radius = Math.min(width, height) * 0.25;
    const angle = d3.scalePoint()
      .domain(sectors)
      .range([0, Math.PI * 2]);

    centers = {};
    sectors.forEach((sector) => {
      const theta = angle(sector);
      centers[sector] = {
        x: width / 2 + radius * Math.cos(theta),
        y: height / 2 + radius * Math.sin(theta),
      };
    });
  }

  function resize() {
    width = chartPanel.clientWidth;
    height = Math.min(620, Math.max(520, window.innerHeight * 0.62));
    svg.attr('width', width).attr('height', height);
    computeCenters();
    simulation
      .force('center', d3.forceCenter(width / 2, height / 2))
      .force('x', d3.forceX((d) => centers[d.sector].x).strength(0.18))
      .force('y', d3.forceY((d) => centers[d.sector].y).strength(0.18))
      .force('collide', d3.forceCollide((d) => d.r + 1.5));
    simulation.alpha(0.9).restart();
  }

  const simulation = d3.forceSimulation(nodes)
    .force('center', d3.forceCenter(0, 0))
    .force('x', d3.forceX(0))
    .force('y', d3.forceY(0))
    .force('collide', d3.forceCollide((d) => d.r + 1.5))
    .force('charge', d3.forceManyBody().strength(-6))
    .on('tick', () => {
      node.attr('transform', (d) => `translate(${d.x},${d.y})`);
    });

  resize();
  window.addEventListener('resize', resize);
})();
JS","yield_time_ms":1000}

